from pathlib import Path
import sys,ast,json,hashlib,time,resource,signal,itertools
from fractions import Fraction as F
root=Path.cwd();sys.path.insert(0,str(root/'code'))
import classification_degenerate_quadric_q4_nil31_I_review as q
start=time.monotonic();signal.alarm(60);resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3));q.N=14
names=dict(zip(['a','b','c','z','w']+['p'+str(i)for i in range(9)],range(14)))
def parse(t,extra={}):
 def rec(n):
  if isinstance(n,ast.Constant):return q.atom(n.value)
  if isinstance(n,ast.Name):return extra[n.id]if n.id in extra else q.atom(1,names[n.id])
  if isinstance(n,ast.UnaryOp):return q.scale(rec(n.operand),-1 if isinstance(n.op,ast.USub)else 1)
  if isinstance(n,ast.BinOp):
   a=rec(n.left)
   if isinstance(n.op,ast.Pow):
    z=q.atom(1)
    for _ in range(n.right.value):z=q.mul(z,a)
    return z
   b=rec(n.right)
   if isinstance(n.op,ast.Add):return q.add(a,b)
   if isinstance(n.op,ast.Sub):return q.add(a,q.scale(b,-1))
   if isinstance(n.op,ast.Mult):return q.mul(a,b)
   if isinstance(n.op,ast.Div):assert len(b)==1 and (0,)*14 in b;return q.scale(a,1/b[(0,)*14])
  raise ValueError(ast.dump(n))
 return rec(ast.parse(t,mode='eval').body)
def Pf4(P,inds):
 a,b,c,d=inds
 return q.add(q.mul(P[a,b],P[c,d]),q.scale(q.mul(P[a,c],P[b,d]),-1),q.mul(P[a,d],P[b,c]))
def p8zero(P):return {e:c for e,c in P.items()if not e[13]}
pth=Path('reports/CLASSIFICATION_PLANE_TRIPLE_Y_WALLS_ORE_20261108.json');d=json.loads(pth.read_text());out=[]
for case in d['cases']:
 extra={'r'+str(i):parse(t)for i,t in enumerate(case['full9_inhomogeneous_P2_unique_particular'])}
 P=q.antisymmetric({ij:q.add(*(parse(case[k][str(ij)],extra)for k in ['saved_P0','full_P1','full_P2_before_elimination']))for ij in q.PAIRS})
 J=q.jacobi(P);exps=sorted(q.monomials(4),reverse=True)
 rows=[{(0,)*5+e[5:]:c for e,c in J[quad].items()if e[:5]==ex}for quad in q.QUADS for ex in exps]
 assert len(rows)==350 and all(row==parse(v)for row,v in zip(rows,case['all350_original_Jacobi_after_elimination']))
 square=parse('2*p8**2'if case['type'].startswith('E1')else'2*p8**2/3');assert rows[54]==rows[279]==square
 D=q.add(*(q.scale(q.mul(q.atom(1,i),Pf4(P,tuple(j for j in range(5)if j!=i))),(-1)**i)for i in range(5)))
 assert D==parse(case['full_actual_D_after_elimination'])
 target=parse('-z**3*(-4*a+p5*w+p7*z)*(-b+p3*z+p6*w)*(p0-4*p1-p7)/4'if case['type'].startswith('E1')else'z**3*(p0-p2)*(-5*a+p1*z+p5*w)**2/5')
 assert p8zero(D)==target
 out.append(dict(type=case['type'],all350_original_rows_independently_reconstructed_and_equal=True,rows54_279_exact_square=True,all126_actual_Pfaffian_independently_reconstructed_and_equal=True,reduced_support_factor_identity=True,full9_P1_and_unique_inhomogeneous9P2_used=True))
source=Path(__file__).read_text();res=dict(task_id='E_reduced_nonnormal',status='PASS',scope='Independent alternate Fraction all350 and fullsignedEulerPf of both whole9P1/unique9P2 sources. Source completeness/fixedminor inverse relies on prior separate reviewed kernel source and full coefficient proof.',cases=out,source_bytes=source,source_sha256=hashlib.sha256(source.encode()).hexdigest(),input_bindings=[dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest())for p in [pth,Path(q.__file__)]],seconds=time.monotonic()-start,maximum_RSS_KiB=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
dest=Path('reports/CLASSIFICATION_PLANE_TRIPLE_Y_WALLS_ROOT_REVIEW_20261108.json');assert not dest.exists();dest.write_text(json.dumps(res,indent=2)+'\n');print(res['status'],res['seconds'],res['maximum_RSS_KiB'])
